// Provider marks: the chat rail row and the chat crumb draw the provider's
// product mark, picked by the provider's `kind` (never its configured name).
// Both paths are the vector marks published by the Simple Icons project
// (CC0, https://github.com/simple-icons/simple-icons, icons/anthropic.svg and
// icons/ollama.svg): Anthropic's "A" glyph and Ollama's llama head, 24x24,
// filled. `name` is the provider's configured name; it is the icon's
// accessible name and its tooltip.
interface ProviderMarkProps extends IconProps { name: string }

