/** ProviderIcon is the mark for a chat provider's `kind`; a kind with no mark
 *  keeps the generic chat glyph. */
export const ProviderIcon = ({ kind, name, color, size = 14 }: ProviderMarkProps & { kind?: string }) =>
  kind === 'anthropic' ? <AnthropicIcon color={color} size={size} name={name} />
    : kind === 'ollama' ? <OllamaIcon color={color} size={size} name={name} />
      : <ChatIcon color={color} size={size} />;

